contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run a single test: call Put with a given lockTime and send `amount` wei.
    function run(uint _lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read balances before
        uint beforeHolderBal = c.Acc(address(this)).balance;
        uint beforeContractBal = address(c).balance;

        bool reverted;
        // perform the call sending Ether
        try c.Put{value: amount}(_lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after
        uint afterHolderBal = c.Acc(address(this)).balance;
        uint afterContractBal = address(c).balance;

        // General invariant:
        // - If call succeeded then holder balance increased by amount and contract balance increased by amount.
        // - If call reverted then neither balance changed.
        assert(reverted ? (afterHolderBal == beforeHolderBal && afterContractBal == beforeContractBal)
                        : (afterHolderBal == beforeHolderBal + amount && afterContractBal == beforeContractBal + amount));
    }

    // receive so the test contract can hold Ether for sending
    receive() external payable {}
}

contract InvMutTest {
