}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test Collect behavior: caller must have at least MinSum and enough balance and unlock passed.
    // Parameters: initial deposit amount to Put, lockTime to make unlockTime in past (0), and collectAmount.
    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        // ensure c has a LogFile to avoid revert in Put/Collect due to Log being uninitialized? The contract allows Log to be unset, Put calls Log.AddMessage which would revert if Log is zero; to avoid that, first set a LogFile by deploying LogFile is not allowed. However, c.SetLogFile must be called with some address; but we cannot create new contracts. To avoid dependency on Log, we instead call fallback via Put through the payable fallback which calls Put(0) — same Log call occurs. Therefore to avoid hitting Log reverts we will not call Put if c.Log is unset; instead, rely on public getters to observe state and only call Collect which will simply not send if preconditions fail. To exercise a successful Collect that transfers funds, we must ensure Log is set and MinSum satisfied — but we cannot deploy LogFile here. Therefore we test a consistency property that Collect, when the external transfer to msg.sender succeeds, reduces balances accordingly; otherwise balances unchanged.
        // Read before-values
        (uint beforeUnlock, uint beforeHolderBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        // Try to call Collect; it may revert due to checks or internal Log call; catch that.
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterHolderBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If call reverted -> state must be unchanged (both holder and contract balances)
        // If not reverted -> either nothing sent (preconditions false) and balances unchanged, or transfer succeeded
        // We cannot directly observe whether the internal call to msg.sender.call returned true, but its effect if it succeeded is that afterHolderBal = beforeHolderBal - collectAmount and afterContractBal = beforeContractBal - collectAmount.
        // Form the assertion to capture both possibilities without underflow: either balances unchanged, or decreased by collectAmount.

        bool unchanged = (afterHolderBal == beforeHolderBal && afterContractBal == beforeContractBal);
        bool decreased = (beforeHolderBal >= collectAmount && beforeContractBal >= collectAmount
                          && afterHolderBal == beforeHolderBal - collectAmount
                          && afterContractBal == beforeContractBal - collectAmount);

        assert(reverted ? unchanged : (unchanged || decreased));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test Put: parameter amount is the Ether forwarded to Put, lockTime arbitrary.
    // We avoid any arithmetic in the assert that can underflow by comparing equality/inequality only.
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read before-values via public getters
        (uint beforeUnlock, uint beforeHolderBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        // Call Put with value=amount and catch revert
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterHolderBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Put reverted, both holder balance and contract balance must be unchanged.
        // If Put succeeded, then both balances must have increased by exactly the sent amount.
        // To avoid subtraction (which could underflow in the checker analysis), express equality by addition:
        // afterHolderBal == beforeHolderBal + amount  <==> afterHolderBal >= beforeHolderBal && afterHolderBal - beforeHolderBal == amount
        // But we avoid subtraction by checking that afterHolderBal >= beforeHolderBal and afterContractBal >= beforeContractBal
        // and that the increments are equal by comparing differences through addition:
        // afterHolderBal == beforeHolderBal + amount  can be checked as (afterHolderBal >= beforeHolderBal) && (afterHolderBal - beforeHolderBal == amount)
        // To avoid -(underflow) we instead check that when succeeded, afterHolderBal >= beforeHolderBal and afterContractBal >= beforeContractBal and
        // (afterHolderBal - beforeHolderBal) == (afterContractBal - beforeContractBal) and that this common increment equals amount by verifying
        // beforeHolderBal + amount == afterHolderBal using a safe require: perform the addition in a way that does not underflow (Solidity 0.8 checks overflow).

        if (reverted) {
            assert(afterHolderBal == beforeHolderBal && afterContractBal == beforeContractBal);
        } else {
            // Put succeeded: both balances must have increased by exactly amount
            // Use Solidity's checked arithmetic in the condition (no raw subtraction in the assert's top-level expression)
            bool holderMatches = (beforeHolderBal + amount) == afterHolderBal;
            bool contractMatches = (beforeContractBal + amount) == afterContractBal;
            assert(holderMatches && contractMatches);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test Put: send `amount` wei with chosen lockTime.
    // We observe Acc[this] and address(c).balance before and after.
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read before-values via public getter
        (uint beforeUnlock, uint beforeHolderBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        // Call Put with value=amount as its own top-level statement and catch revert
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterHolderBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Single assert expressing the general rule:
        // If reverted then balances unchanged; else both increased exactly by amount.
        assert(
            (reverted && afterHolderBal == beforeHolderBal && afterContractBal == beforeContractBal)
            ||
            (!reverted && (beforeHolderBal + amount) == afterHolderBal && (beforeContractBal + amount) == afterContractBal)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: set MinSum and LogFile, call Initialized, then Put some funds (via payable),
    // then attempt Collect for some amount. We assert that if Collect did NOT revert,
    // then the holder balance stored in the public getter decreased by exactly the amount
    // and the contract's Ether balance decreased by at least that amount (exactly that amount
    // minus any prior changes in this test contract which doesn't receive funds from c).

    receive() external payable {}

    function run(uint minSum, address logAddr, uint lockTime, uint putAmount, uint collectAmount) public payable {
        // ensure this contract has enough balance to send putAmount
        require(address(this).balance >= putAmount);

        // Set MinSum and LogFile and initialize
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Read before-values
        uint beforeHolderBalance = c.Acc(address(this)).balance;
        uint beforeContractBalance = address(c).balance;

        // Put funds into c for this test contract as msg.sender == address(this)
        c.Put{value: putAmount}(lockTime);

        // Read after put
        uint afterPutHolderBalance = c.Acc(address(this)).balance;
        uint afterPutContractBalance = address(c).balance;

        // Sanity: afterPutHolderBalance should have increased by putAmount
        // (we won't assert here, but rely on general property below)

        // Now attempt Collect; capture whether it reverted
        bool reverted;
        // We must call Collect as a top-level statement; use try/catch on low-level call via address(c).
        // But constraint requires using c.f directly for state-changing calls. So use try/catch with c.Collect.
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read final values
        uint finalHolderBalance = c.Acc(address(this)).balance;
        uint finalContractBalance = address(c).balance;

        // General rule: If Collect did not revert then holder balance decreased by exactly collectAmount
        // and contract balance decreased by at least collectAmount.
        // Use a single assert expressing that implication.
        assert(reverted || (afterPutHolderBalance == beforeHolderBalance + putAmount && finalHolderBalance + collectAmount == afterPutHolderBalance && afterPutContractBalance >= finalContractBalance && afterPutContractBalance - finalContractBalance >= collectAmount));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    // params: minSum to set, logAddr to set, lockTime for Put, putAmount to deposit, collectAmount to attempt to collect
    function run(uint minSum, address logAddr, uint lockTime, uint putAmount, uint collectAmount) public payable {
        // ensure this test contract has enough balance to fund Put
        require(address(this).balance >= putAmount);

        // Initialize c: set MinSum, LogFile and mark initialized
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // read holder tuple via public getter Acc(address) which returns (uint unlockTime, uint balance)
        (uint beforeUnlock, uint beforeHolderBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        // deposit into c as msg.sender == address(this)
        c.Put{value: putAmount}(lockTime);

        // read after put
        (uint midUnlock, uint afterPutHolderBalance) = c.Acc(address(this));
        uint midContractBalance = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read final state
        (uint finalUnlock, uint finalHolderBalance) = c.Acc(address(this));
        uint finalContractBalance = address(c).balance;

        // If Collect did not revert then: (1) afterPutHolderBalance reflected the deposit, (2) finalHolderBalance = afterPutHolderBalance - collectAmount,
        // and (3) contract balance decreased by at least collectAmount.
        // Note: require arithmetic that avoids underflow in the assert by structuring implications.
        assert(reverted || (afterPutHolderBalance >= beforeHolderBalance && afterPutHolderBalance == beforeHolderBalance + putAmount && finalHolderBalance + collectAmount == afterPutHolderBalance && midContractBalance >= finalContractBalance && midContractBalance - finalContractBalance >= collectAmount));
    }
}

