contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // accept ETH when C sends funds to this test (e.g., during Collect)
    receive() external payable {}

    // Test: Put must increase both the recorded holder balance and address(c).balance by exactly the sent amount (or at least not decrease them if zero is sent).
    // We use two parameters: lockTime and amount to send to Put.
    function run(uint lockTime, uint amount) public payable {
        // ensure this contract has enough balance to send `amount` to c
        require(address(this).balance >= amount);

        // Read recorded holder state and contract balance before
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // Call Put sending `amount` wei
        c.Put{value: amount}(lockTime);

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General invariant: the recorded balance and contract balance do not decrease; they increase by at least `amount` in sum.
        // More specifically: afterBalance >= beforeBalance and afterCbal >= beforeCbal and
        // the recorded balance increase is <= contract balance increase (i.e., recorded can't grow more than contract's ether)
        // This avoids equality assumptions about logging or other effects but enforces monotonicity and consistency.
        assert(afterBalance >= beforeBalance && afterCbal >= beforeCbal && (afterBalance - beforeBalance) <= (afterCbal - beforeCbal));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run attempts to Put some value with a lockTime then tries to Collect amount _am.
    // It asserts that when Collect call does not revert, the holder balance reported by c decreased by _am
    // and address(c).balance decreased by at least _am (contract sent Ether out).
    function run(uint _lockTime, uint _am, uint putAmount) public payable {
        require(address(this).balance >= putAmount);
        // Ensure MinSum and LogFile and initialization don't block Put: set MinSum to 0 and set a LogFile
        // These calls must be top-level changing calls.
        // Provide a dummy LogFile by using the existing LogFile contract deployed at address(c) if possible.
        // However we must only call c's public methods. We'll set MinSum to 0 and initialize Log to address(c) (allowed)
        c.SetMinSum(0);
        c.SetLogFile(address(c));
        c.Initialized();

        // record balances before Put
        uint beforeHolderBalance = c.Acc(address(this)).balance; // using public getter
        uint beforeContractBalance = address(c).balance;

        // perform Put sending putAmount wei
        c.Put{value: putAmount}(_lockTime);

        // after put, try to Collect _am and catch revert
        bool reverted;
        // record balances after Put before Collect
        uint midHolderBalance = c.Acc(address(this)).balance;
        uint midContractBalance = address(c).balance;

        try c.Collect{value:0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after Collect attempt
        uint afterHolderBalance = c.Acc(address(this)).balance;
        uint afterContractBalance = address(c).balance;

        // If Collect did not revert then the holder's recorded balance must have decreased by exactly _am
        // and the contract's balance must have decreased by at least _am (the transfer out may fail to send full
        // if no funds, but if Collect succeeded the Ether must have left contract). We use >= to avoid underflow.
        assert(reverted || (midHolderBalance == beforeHolderBalance + putAmount && // sanity: Put increased holder
               afterHolderBalance + _am == midHolderBalance &&
               midContractBalance >= afterContractBalance + _am));
    }

    receive() external payable { }
}

