contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry test: try to call Collect and assert that if it did NOT revert,
    // then the public getter values observed just before the call satisfied the Collect requirements
    function run(uint _am) public payable {
        // No precondition on _am; keep function payable to satisfy interface but we won't send ETH during Collect.

        // Make contract configurable once: set MinSum = 0, set LogFile to c itself, and mark initialized so Collect can proceed.
        // These calls may revert if already initialized, but c is fresh for each checker run per instructions.
        c.SetMinSum(0);
        c.SetLogFile(address(c));
        c.Initialized();

        // Ensure there is some holder state for this contract address by performing a Put with 0 value and 0 lock time.
        // Use 0 value to avoid triggering add_uint256 overflow in the target during tests.
        c.Put{value: 0}(0);

        // Read the observable holder state for this test contract immediately before attempting Collect.
        (uint beforeUnlock, uint beforeHolderBalance) = c.Acc(address(this));
        uint beforeMin = c.MinSum();

        // Attempt Collect and record whether it reverted.
        bool reverted;
        try c.Collect{value:0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Assert: if Collect did not revert, then the observed state satisfied the three Collect requirements.
        // 1) holder balance >= MinSum
        // 2) holder balance >= _am
        // 3) block.timestamp > unlockTime
        // We cannot refer to the runtime block.timestamp directly here; however, the getter returned beforeUnlock
        // was read at the same transaction and represents the stored unlockTime. The rule asserts that success implies
        // that the current block.timestamp (at call time) was strictly greater than beforeUnlock. Since we cannot
        // read block.timestamp inside the assert condition in terms of c's internals, we express the implication
        // purely from observed storage: success implies the three numeric relations between read values and _am.
        assert(reverted
            || (
                beforeHolderBalance >= beforeMin
                && beforeHolderBalance >= _am
                // The contract's Collect requires block.timestamp > unlockTime; because the test's call happened in the same
                // transaction after reading beforeUnlock, the only way Collect could succeed is if that condition held at call time.
                // We therefore include it as part of the necessary conditions: the stored unlockTime must be strictly less than block.timestamp.
                && (beforeUnlock < block.timestamp)
            )
        );
    }

    // receive to accept ETH if needed by Put
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test the invariant: a successful Put{value: amt}(_lock) increases the public-recorded balance
    // for this contract by at least amt (i.e., the holder's stored balance >= amt after Put when starting from zero).
    function run(uint _lockTime, uint amt) public payable {
        require(address(this).balance >= amt, "insufficient test balance");

        // Initialize c so that Put can run without reverting due to initialization flags.
        // c is fresh for each checker run, so these calls should succeed.
        c.SetMinSum(0);
        c.SetLogFile(address(c));
        c.Initialized();

        // Ensure starting holder state for this contract is observed (may be zero).
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // We will perform Put with value amt. Send ETH from this contract to c.
        c.Put{value: amt}(_lockTime);

        // Read the holder state after the Put.
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // General rule: If beforeBalance was 0, then afterBalance must be at least amt.
        // (This avoids risky subtraction in the assert and focuses on the effect of a single Put on an initially empty holder.)
        assert(!(beforeBalance == 0) || (afterBalance >= amt));
    }

    // Allow this test contract to receive ETH so the checker can fund it before calling run(...).
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that a successful Collect reduces the stored holder balance exactly by the collected amount.
    function run(uint _am, uint _lock) public payable {
        require(address(this).balance >= _am, "insufficient test balance");

        // Initialize c so that Put/Collect/MinSum checks proceed normally.
        c.SetMinSum(0);
        c.SetLogFile(address(c));
        c.Initialized();

        // Ensure there is enough recorded balance and that unlockTime is in the past so Collect can succeed.
        // First, deposit some ETH via Put so Acc[msg.sender].balance >= _am.
        c.Put{value: _am}(_lock);

        // Read holder state before Collect.
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Advance time requirement: if unlockTime is in the future, do another Put with zero lock to keep unlockTime unchanged
        // and ensure unlock condition fails if lock not passed. We avoid manipulating block.timestamp; instead require that
        // beforeUnlock is less than block.timestamp so Collect has chance to succeed. If not, we still perform the call and
        // observe whether it reverts.

        bool reverted;
        try c.Collect{value: 0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read holder state after Collect attempt.
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // If Collect succeeded (not reverted), then the stored balance must have decreased by exactly _am.
        assert(reverted || (afterBalance + _am == beforeBalance));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll try to arrange a holder with sufficient balance and unlockTime so Collect can succeed,
    // then call Collect and assert that when it didn't revert, both the on-chain balance and the
    // stored balance for this contract's address decreased by exactly the collected amount.
    function run(uint putLockTime, uint putValue, uint collectAmount) public payable {
        // ensure this test contract has enough balance to fund the Put call
        require(address(this).balance >= putValue);

        // initialize MinSum to 0 and LogFile to an existing LogFile so Put works even if not initialized
        // These calls may revert if intitalized already true in c; but c is freshly deployed by checker.
        c.SetMinSum(0);
        // deploy a LogFile by using the existing LogFile in this environment is not allowed, so we pass address(c) as dummy
        // but SetLogFile expects an address of LogFile; passing address(this) could break types; instead use address(c)
        // Since Log is only used for AddMessage and its type is LogFile, we can pass address(c) (it will typecast), as done in original contract usage.
        c.SetLogFile(address(c));

        // mark initialized so later actions don't change these settings; not strictly needed but keeps state stable
        c.Initialized();

        // Record balances before Put
        uint beforeContractBal = address(c).balance;
        // Read holder balance for this test contract (auto getter Acc(address) returns (uint unlockTime, uint balance))
        (uint beforeUnlock, uint beforeHolderBal) = c.Acc(address(this));

        // Perform Put to send Ether into c for this test contract as holder
        c.Put{value: putValue}(putLockTime);

        // After Put balances
        uint afterPutContractBal = address(c).balance;
        (uint afterPutUnlock, uint afterPutHolderBal) = c.Acc(address(this));

        // Sanity: Put must have increased contract balance by putValue and holder balance by putValue
        // We don't assert that here because Put could set unlockTime differently; we'll proceed to try Collect.

        // Ensure the unlock time has passed so Collect can succeed: we choose collect only if block.timestamp > unlockTime
        // We cannot advance time; but if unlock not passed, Collect will revert. We'll attempt Collect and observe revert flag.
        bool reverted;
        // Capture balances before Collect
