        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        // Access Log.LastMsg by reading History length and last element: History is public, but LastMsg isn't public.
        // However LogFile has public array History, we can read last entry if History.length>0
        LogFile log = LogFile(address(c.Log()));
        uint histLen = log.HistoryLength();
        address lastSender;
        uint lastVal;
        string memory lastData;
        if (histLen > 0) {
            (lastSender, lastVal, lastData) = log.getLastSafe(histLen - 1);
        } else {
            lastSender = address(0);
            lastVal = 0;
            lastData = "";
        }

        // The general property: if Collect did NOT revert, and beforeBalance>=minSum and beforeBalance>=collectAmount
        // and the lock had expired (block.timestamp > beforeUnlock), then afterBalance == beforeBalance - collectAmount
        // and the log records a Collect entry with the amount and sender.
        bool condCanCollect = (beforeBalance >= minSum) && (beforeBalance >= collectAmount) && (block.timestamp > beforeUnlock);

