            assert(keccak256(abi.encodePacked(lastData)) == keccak256(abi.encodePacked("Collect")));
        }

        // Final general assertion: either Collect reverted, or the observed invariants hold
        assert(reverted || (afterBalance + collectAmount == beforeBalance && lastSender == address(this) && lastVal == collectAmount && keccak256(abi.encodePacked(lastData)) == keccak256(abi.encodePacked("Collect"))));
    }

