    function run(uint _am, uint prereq_amount) public payable {
        // ensure we can send prereq_amount when calling Put
        require(address(this).balance >= prereq_amount);

        // make sure contract has a LogFile and MinSum and is initialized appropriately
        // We call SetMinSum and SetLogFile and Initialized first (these may revert if already initialized in other scenarios,
        // but here c is freshly deployed by the checker so these will succeed). Use try/catch to continue even if they revert.
        try c.SetMinSum(1) {
        } catch {}
        try c.SetLogFile(address(this)) {
        } catch {}
        try c.Initialized() {
        } catch {}

        // Record c's balance before any actions
        uint beforeCbal = address(c).balance;
        // Read holder state for this contract's address before
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));

        // Fund the holder by calling Put with prereq_amount (may revert)
        bool putReverted = false;
        if (prereq_amount > 0) {
            try c.Put{value: prereq_amount}(0) {
                putReverted = false;
            } catch {
                putReverted = true;
            }
        }

        // Record balances after Put attempt and before Collect
        uint midCbal = address(c).balance;
        (uint midUnlock, uint midBal) = c.Acc(address(this));

        // Attempt Collect and record whether it reverted
        bool collectReverted = false;
        // Use try/catch to observe revert without bubbling
        try c.Collect(_am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-state
        uint afterCbal = address(c).balance;
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        // If Collect did not revert then either it didn't send ETH (no change in contract or recorded balance)
        // or it did send ETH: then recorded balance decreased and contract balance decreased by same nonzero amount.
        // Express as: collectReverted OR (no change) OR (decrease equal and nonzero)
        bool noChange = (afterBal == midBal) && (afterCbal == midCbal);
        bool decreaseMatches = false;
        if (midBal >= afterBal && midCbal >= afterCbal) {
            uint recordedDec = midBal - afterBal;
            uint contractDec = midCbal - afterCbal;
            // recordedDec and contractDec must be equal and nonzero to consider ETH was sent out
            decreaseMatches = (recordedDec == contractDec) && (recordedDec != 0);
        }

        assert(collectReverted || noChange || decreaseMatches);
    }

    // receive to accept ETH when SetLogFile may try to send or when calls expect it
    receive() external payable {}
}

