    // We will: 1) ensure MinSum is 0 and LogFile set and contract initialized flag cleared by calling SetMinSum and SetLogFile
    // 2) Put some Ether from this contract into c for msg.sender == address(this) (InvMutTest)
    // 3) Attempt Collect of amount 'collectAmt' and observe whether it reverted or succeeded
    // The invariant: if Collect succeeds (no revert and transfer succeeded), then Acc[address(this)].balance decreased by collectAmt

    receive() external payable {}

    function run(uint lockTime, uint putAmt, uint collectAmt, address logAddress) public payable {
        require(address(this).balance >= putAmt + 1 wei, "need ETH to fund Put and leave some for other calls");
        // Initialize min sum and log file (these calls must be allowed only before Initialized)
        // They may revert if intitalized is true, but on fresh c they're allowed.
        c.SetMinSum{value:0}(0);
        c.SetLogFile{value:0}(logAddress);
        // Make sure contract is not marked initialized yet (we cannot read it directly), but above calls succeed on fresh deploy.

        // Record balance before operations
        uint beforeContractBalance = address(c).balance;
        (uint accBalanceBefore, uint accUnlock) = c.Acc(address(this));

        // Put Ether into c as this contract (InvMutTest) using fallback or Put
        // call Put with given lockTime and send putAmt
        require(address(this).balance >= putAmt, "not enough balance for putAmt");
        c.Put{value: putAmt}(lockTime);

        // Read balances after Put
        uint afterPutContractBalance = address(c).balance;
        (uint accBalanceAfterPut, ) = c.Acc(address(this));

        // Now try Collect of collectAmt and capture whether it reverted and whether transfer succeeded
        bool reverted;
        bool transferSucceeded;
        // we cannot directly observe internal transfer success except via effects; Collect attempts msg.sender.call which will send Ether to this contract
        // To detect transfer success, we record this contract's ETH balance before and after Collect; if increased by collectAmt then transfer succeeded
        uint ourBalBeforeCollect = address(this).balance;
        (reverted) = (false);
        try c.Collect{value:0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint ourBalAfterCollect = address(this).balance;
        if (!reverted) {
            // If Collect did not revert, transfer may still fail internally (but Collect only proceeds to call when conditions met, then uses low-level call and checks _s)
            // In the contract, they check _s and only then subtract balance and log. So if transfer failed, acc.balance should NOT be decreased.
            transferSucceeded = (ourBalAfterCollect == ourBalBeforeCollect + collectAmt);
        } else {
            transferSucceeded = false;
        }

        // Read account balance after Collect
        (uint accBalanceAfterCollect, ) = c.Acc(address(this));
        uint afterCollectContractBalance = address(c).balance;

        // Final invariant: if Collect returned without revert AND the transfer to this contract succeeded, then
        // accBalanceAfterCollect == accBalanceAfterPut - collectAmt AND address(c).balance decreased by collectAmt
        // We express as: if (!reverted && transferSucceeded) then those equalities hold
        assert((reverted || !transferSucceeded) || (
            accBalanceAfterCollect + collectAmt == accBalanceAfterPut
            && afterPutContractBalance == afterCollectContractBalance + collectAmt
        ));
    }
}

